PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <https://w3id.org/engineering-data/v1/ref/>
SELECT ?point ?ts WHERE {
  ?zone rdfs:label "Perimeter_bot_ZN_3" .
  ?point brick:hasLocation ?zone ; a brick:AirTemperature .
  ?point ref:hasExternalReference ?ts .
  OPTIONAL { ?point ref:hasTimeseriesId ?id }
}

